"""Gerar documentos revisáveis a partir da avaliação efetivamente executada."""
import argparse
import json
import re
from pathlib import Path
import shutil
import pandas as pd
from sbsr_lidar.storage import read_json,atomic_write_json


def number(value, decimals=3):
    return 'não estimado' if value is None or pd.isna(value) else f'{float(value):.{decimals}f}'


def prose(lines):
    """Espaçar unidades/números em prosa, preservando código e caminhos."""
    chunks=re.split(r'(```[\s\S]*?```|`[^`]*`)', '\n'.join(lines))
    for i,text in enumerate(chunks):
        if text.startswith('`'): continue
        text=re.sub(r'\b(etapa|classe|classes|grade|halo|tem|ganhou|perdeu|omite|em|de|e|a|por|que|para|com|referência|cenários|principal|adverso|propostos|protocolo|top|fator|restaram|houver|suficiente|mínimo|reservar|as|os|inicial|célula|EPSG|origem|conectividade|constantes|pesos|tolerância|total|sementes|min|escalas|subamostragem|representam|relaxar)(?=\d)',r'\1 ',text,flags=re.I)
        text=re.sub(r'(?<=[;:])(?=\d)',' ',text)
        text=re.sub(r'(?<=[A-Za-zÀ-ÿ\)]),(?=\d)',', ',text)
        text=re.sub(r'(?<=\d)(?=(?:m²|GiB|MiB|m\b|s\b))',' ',text)
        text=re.sub(r'(?<=\d)(?=(?:feições|candidatos|corredores|blocos|unidades|pares|registros|tarefas|janelas|arquivos|cenários|produtos|postos)\b)',' ',text)
        text=text.replace('temrho','tem rho').replace('deΔ','de Δ').replace('deO','de O').replace('A+3D25','A+3D de 25').replace('Ncomponentes','N_componentes')
        text=text.replace('P.buffer10','P.buffer(10 m)').replace('P.buffer5/10','P.buffer(5/10 m)')
        text=text.replace('gates','condições de execução').replace('Gates','Condições de execução')
        chunks[i]=text
    return ''.join(chunks)


